package jp.co.example.app.controller;

import java.util.List;

import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RestController;

import jp.co.example.app.dto.UserDto;
import jp.co.example.app.service.UserService;
import lombok.RequiredArgsConstructor;

@RestController
@RequiredArgsConstructor
public class UserController {

    private final UserService userService;

    @GetMapping("/users/{id}")
    public UserDto findOne(@PathVariable String id) {
        return userService.findById(id);
    }
}

@Data
@Builder
public class KeyIssueRequest {
    private final String cardId;
    private final int keyVersion;
}

@Service
@RequiredArgsConstructor
@Slf4j
public class KeyIssueService {

    private final KeyRepository keyRepository;

    public String issue(KeyIssueRequest req) {
        log.info("issue cardId={}", req.getCardId());
        keyRepository.save(new KeyEntity(req.getCardId(), req.getKeyVersion(), "ACTIVE"));
        return "OK";
    }
}
